def normalizar_generos(apps, schema_editor):
    """Pasa los géneros escritos a mano a la nueva lista cerrada (o los deja vacíos)."""
    from biblioteca.services.generos import sugerir

    Libro = apps.get_model("biblioteca", "Libro")
    for libro in Libro.objects.exclude(genero=""):
        nuevo = sugerir(libro.genero)
